    return BoundingBox2{Point2d(0, 0), Point2d(0, 0)};
}

if (points.size() == 1) {
    return BoundingBox2{points[0], points[0]};
}

// Compute convex hull using Graham scan or Andrew's monotone chain
// Then for each edge of the hull, compute the bounding box

// Actually, for the minimum area bounding box, we need to:
// 1. Compute convex hull
// 2. For each edge of the hull, rotate points so edge is horizontal
// 3. Find AABB of rotated points
// 4. Track minimum area one

// Let me implement the convex hull first (Andrew's monotone chain)
std::vector<Point2d> hull;

// Sort points by x, then by y
std::vector<Point2d> sorted = points;
std::sort(sorted.begin(), sorted.end(), [](const Point2d& a, const Point2d& b) {
    if (a.x < b.x) return true;
    if (a.x > b.x) return false;
    return a.y < b.y;
});

// Build lower hull
for (const auto& p : sorted) {
    while (hull.size() >= 2) {
        Point2d p1 = hull[hull.size() - 2];
        Point2d p2 = hull[hull.size() - 1];
        // Cross product to check orientation
        double cross = (p2.x - p1.x) * (p.y - p1.y) - (p2.y - p1.y) * (p.x - p1.x);
        if (cross <= 0) {
            hull.pop_back();
        } else {
            break;
        }
    }
    hull.push_back(p);
}

// Build upper hull
int lower_size = hull.size();
for (int i = sorted.size() - 2; i >= 0; i--) {
    const Point2d& p = sorted[i];
    while (hull.size() > lower_size) {
        Point2d p1 = hull[hull.size() - 2];
        Point2d p2 = hull[hull.size() - 1];
        double cross = (p2.x - p1.x) * (p.y - p1.y) - (p2.y - p1.y) * (p.x - p1.x);
        if (cross <= 0) {
            hull.pop_back();
        } else {
            break;
        }
    }
    hull.push_back(p);
}

// Remove last point of upper hull (it's same as first point of lower hull)
if (hull.size() > 1) {
    hull.pop_back();
}

